/* From Uiverse.io by OnCloud125252 - Tags: input, dark, search */
.__UIV_SCOPE__ .inputBox_container {
  display: flex;
  align-items: center;
  flex-direction: row;
  max-width: 14em;
  width: fit-content;
  height: fit-content;
  background-color: #5c6370;
  border-radius: 0.8em;
  overflow: hidden;
}

.__UIV_SCOPE__ .search_icon {
  height: 1em;
  padding: 0 0.5em 0 0.8em;
  fill: #abb2bf;
}

.__UIV_SCOPE__ .inputBox {
  background-color: transparent;
  color: #ffffff;
  outline: none;
  width: 100%;
  border: 0;
  padding: 0.5em 1.5em 0.5em 0;
  font-size: 1em;
}

.__UIV_SCOPE__ ::placeholder {
  color: #abb2bf;
}
